class Solution:
    def minSubArrayLen(self, goal: int, nums: List[int]) -> int:
        l = s = 0; best = inf
        for r, x in enumerate(nums):
            s += x
            while s >= goal:
                best = min(best, r - l + 1); s -= nums[l]; l += 1
        return 0 if best == inf else best

