function minSubArrayLen(goal, nums) {
  const pre = [0]; for (const x of nums) pre.push(pre[pre.length - 1] + x);
  let best = Infinity;
  for (let j = 1; j < pre.length; j++) {
    let lo = 0, hi = j - 1, f = -1;
    while (lo <= hi) { const m = (lo + hi) >> 1; if (pre[j] - pre[m] >= goal) { f = m; lo = m + 1; } else hi = m - 1; }
    if (f >= 0) best = Math.min(best, j - f);
  }
  return best === Infinity ? 0 : best;
}
